import sys

def generate_graph(k):
    if k == 1:
        return 2, ["NY", "YN"]

    n = 2
    while True:
        if k <= (n - 1) * (n - 2) // 2 + 1:
            break
        n += 1

    graph = [['N'] * n for _ in range(n)]
    graph[0][1] = 'Y'
    graph[1][0] = 'Y'

    count = 1
    for i in range(2, n):
        for j in range(i):
            if count <= k:
                graph[i][j] = 'Y'
                graph[j][i] = 'Y'
                count += 1
            else:
                break

    return n, [''.join(row) for row in graph]

def main():
    k = int(sys.stdin.read().strip())
    n, graph = generate_graph(k)
    sys.stdout.write(f"{n}\n")
    for line in graph:
        sys.stdout.write(f"{line}\n")

if __name__ == "__main__":
    main()
